import * as THREE from '../vendor/three.module.js';
// Reuse topology and GPU buffers. This is the same short arched centreline,
// updated continuously; no TubeGeometry allocation/disposal per animation frame.
export function updateTentacleGeometry(geometry,from,to,progress){const positions=geometry.attributes.position,normals=geometry.attributes.normal,delta=new THREE.Vector3(to.x-from.x,to.y-from.y,to.z-from.z),up=new THREE.Vector3(0,1,0),tangent=new THREE.Vector3(),u=new THREE.Vector3(),v=new THREE.Vector3(),normal=new THREE.Vector3(),centre=new THREE.Vector3();for(let i=0;i<=24;i++){const t=i/24*progress;centre.set(from.x+delta.x*t,from.y+delta.y*t+Math.sin(t*Math.PI)*.025,from.z+delta.z*t);tangent.copy(delta);tangent.y+=Math.cos(t*Math.PI)*.025*Math.PI;tangent.normalize();u.crossVectors(tangent,up);if(u.lengthSq()<1e-8)u.set(1,0,0);else u.normalize();v.crossVectors(tangent,u).normalize();for(let j=0;j<=8;j++){const a=j/8*Math.PI*2,k=i*9+j;normal.copy(u).multiplyScalar(Math.cos(a)).addScaledVector(v,Math.sin(a));positions.setXYZ(k,centre.x+.075*normal.x,centre.y+.075*normal.y,centre.z+.075*normal.z);normals.setXYZ(k,normal.x,normal.y,normal.z);}}positions.needsUpdate=true;normals.needsUpdate=true;geometry.computeBoundingBox();geometry.computeBoundingSphere();}
